export interface RealJobSeed {
  /** job-crawler-automation seeds/snapshot/jobs.db의 normalized_jobs.id (참고용, 재노출 안 함) */
  realId: number;
  company: string;
  title: string;
  sourceUrl: string;
  employmentType: 'FULL_TIME' | 'CONTRACT' | 'INTERN' | 'PART_TIME';
  experienceType: 'NEWCOMER' | 'EXPERIENCED' | 'BOTH' | 'IRRELEVANT';
  /** 오늘(고정 기준일)로부터 며칠 뒤가 마감인지 */
  daysOut: number;
  viewCount: number;
  bookmarkCount: number;
  commentCount: number;
  bookmarked: boolean;
  body: string | null;
  requirements: string | null;
  /** 확신 있는 대기업만 채움, 나머지는 undefined(회색 placeholder로 렌더링) */
  logoDomain?: string;
}

